from html.parser import HTMLParser
from pathlib import Path
from hashlib import sha256
import json, re

class PolicyText(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.hidden = 0
        self.parts = []

    def handle_starttag(self, tag, attrs):
        if tag in {'style', 'script'}:
            self.hidden += 1
        if tag in {'p', 'li', 'h1', 'h2', 'h3', 'h4', 'br'}:
            self.parts.append('\n')

    def handle_endtag(self, tag):
        if tag in {'style', 'script'} and self.hidden:
            self.hidden -= 1
        if tag in {'p', 'li', 'h1', 'h2', 'h3', 'h4'}:
            self.parts.append('\n')

    def handle_data(self, data):
        if not self.hidden:
            self.parts.append(data.replace('\n', ' '))

base = Path('products/services/nlnet-ai-policy-followup')
raw = (base / 'raw/policy.html').read_bytes()
parser = PolicyText()
parser.feed(raw.decode('utf-8'))
lines = [' '.join(line.split()) for line in ''.join(parser.parts).splitlines()]
lines = [line for line in lines if line]
pattern = re.compile(r'applican|propos|responsib|disclos|licen[cs]|generative|human|deliverable|autonomous|effective|version', re.I)
selected = sorted({n for i, line in enumerate(lines) if pattern.search(line) for n in range(max(0, i-1), min(len(lines), i+2))})
result = {'source': 'https://nlnet.nl/foundation/policies/generativeAI/2.0/', 'sha256': sha256(raw).hexdigest(), 'matches_fetch_receipt': sha256(raw).hexdigest() == '4590d76cce8fdb608efe2f1c6eb518d432491c8c2c26992a0be304013d9f8fe8', 'method': 'Normalized HTML text with neighboring lines. Verify applicability and decisive wording in the original.', 'passages': [{'line': i+1, 'text': lines[i]} for i in selected]}
output = base / 'policy-passages.json'
output.write_text(json.dumps(result, ensure_ascii=False, indent=2) + '\n', encoding='utf-8')
print(json.dumps({'artifact': str(output), 'receipt_match': result['matches_fetch_receipt'], 'passage_count': len(selected)}))
